SELECT CASE WHEN amount >= 1310 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, CASE WHEN discount >= 0.44 THEN 'PREMIUM' ELSE 'STANDARD' END AS discount_tier, COUNT(CASE WHEN channel = 'partner' THEN 1 END) AS partner_count, COUNT(*) AS row_count, STDDEV_SAMP(amount) AS amount_stddev, SIZE(COLLECT_SET(channel)) AS num_channels, DENSE_RANK() OVER (PARTITION BY CASE WHEN amount >= 1310 THEN 'HIGH' ELSE 'LOW' END ORDER BY STDDEV_SAMP(amount) DESC) AS amount_stddev_dense_rank FROM orders GROUP BY 1, 2 HAVING SIZE(COLLECT_SET(channel)) >= 1;
